//! Frame selection for 24/25/30/60 fps sources generated by ffmpeg testsrc.
//!
//! The test skips when ffmpeg is not installed. Each source is generated
//! all-intra so seeking to an exact timestamp returns exactly that frame.

use std::path::{Path, PathBuf};
use std::process::Command;

use motioner_io::{decode_frame, probe_video, FfmpegLocation};

fn ffmpeg_available() -> bool {
    Command::new("ffmpeg")
        .arg("-version")
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .is_ok_and(|status| status.success())
}

fn generate(dir: &Path, fps: u32) -> Option<PathBuf> {
    let path = dir.join(format!("src{fps}.mp4"));
    let status = Command::new("ffmpeg")
        .args([
            "-v",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            &format!("testsrc=size=160x90:rate={fps}:duration=2"),
            "-c:v",
            "libx264",
            "-g",
            "1",
            "-keyint_min",
            "1",
            "-pix_fmt",
            "yuv420p",
            &path.to_string_lossy(),
        ])
        .status()
        .ok()?;
    status.success().then_some(path)
}

#[test]
#[allow(clippy::cast_precision_loss)]
fn every_source_rate_selects_the_expected_frame() {
    if !ffmpeg_available() {
        return;
    }
    let dir = std::env::temp_dir().join(format!("motioner_video_frames_{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();

    for fps in [24_u32, 25, 30, 60] {
        let Some(path) = generate(&dir, fps) else {
            continue;
        };
        let info = probe_video(&path, &FfmpegLocation::FromEnvOrPath).unwrap();
        assert_eq!(info.width, 160);
        assert_eq!(info.height, 90);
        assert!((info.fps() - f64::from(fps)).abs() < 0.001);

        // A 60 fps composition selects frame 30 at 0.5 s.
        let composition = motioner_core::FrameRate::new(60, 1).unwrap();
        let mut video = motioner_core::VideoContent::new(path.to_string_lossy().to_string(), 0);
        video.asset = Some(motioner_core::VideoAsset {
            key: motioner_core::ImageKey::from_bytes([0; 32]),
            width: info.width,
            height: info.height,
            fps: motioner_core::FrameRate::new(fps, 1).unwrap(),
            duration: info.duration,
        });
        let source_frame = video.source_frame(30, composition).unwrap();
        assert_eq!(source_frame, i64::from(fps / 2));

        let seconds = source_frame as f64 / f64::from(fps);
        let first = decode_frame(&path, seconds, 160, 90, &FfmpegLocation::FromEnvOrPath).unwrap();
        let next_seconds = (source_frame + 1) as f64 / f64::from(fps);
        let second =
            decode_frame(&path, next_seconds, 160, 90, &FfmpegLocation::FromEnvOrPath).unwrap();
        assert_eq!(first.len(), 160 * 90 * 4);
        assert_ne!(first, second, "consecutive frames must differ at {fps} fps");
    }

    let _ = std::fs::remove_dir_all(&dir);
}
